import { useEffect, useRef, useState } from "react";
import * as d3 from "d3";

function ParallelSets({hoveredItem, foodItems, displayedNutrients, comparingItem ,selectedItems}) {
    const svgRef = useRef();
    
  useEffect(() => {
    d3.select(svgRef.current).selectAll("*").remove();

    const width = 600;
    const height = 450; // i increased the height to make room for the tilted labels
    const margin = { top: 40, right: 40, bottom: 70, left: 40 };

      const itemsToDraw = selectedItems?.length
          ? comparingItem
          : hoveredItem
              ? [hoveredItem]
              : foodItems.length > 0
                  ? foodItems  // if no food items are selected for comparizon then we show all of them
                  : [];

          d3.select(svgRef.current).selectAll("*").remove();
        if (itemsToDraw.length === 0) return;
        //console.log('====================================');
        //console.log(itemsToDraw.color);
        //console.log('====================================');
    

    const svg = d3
      .select(svgRef.current)
      .attr("width", width)
      .attr("height", height)
      .append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const xScale = d3
      .scalePoint()
      .domain(displayedNutrients)
      .range([0, width - margin.left - margin.right]);

    // Create yScales for each nutrient
    const yScales = {};
    displayedNutrients.forEach((nutrient) => {
      const maxVal = d3.max(foodItems, (item) => item.food[nutrient] || 0) || 1;
      yScales[nutrient] = d3
        .scaleLinear()
        .domain([0, maxVal])
        .range([height - margin.top - margin.bottom, 0]);
    });

    // Draw axes
    displayedNutrients.forEach((nutrient) => {
      if (!yScales[nutrient]) return; // Ensure yScale exists

      svg.append("g")
        .attr("transform", `translate(${xScale(nutrient)}, 0)`)
        .call(d3.axisLeft(yScales[nutrient]));

      svg.append("text")
        .attr("x", xScale(nutrient))
        .attr("y", height - margin.top - margin.bottom + 45)
        //.attr("y", height - margin.top - margin.bottom + 25) 
        //.attr("text-anchor", "middle")
        .attr("text-anchor", "end")  // to align text
        .attr("transform", `rotate(-30, ${xScale(nutrient)}, ${height - margin.top - margin.bottom + 25})`) //  Rotating text to avoid overlap
        .style("font-size", "12px")
        .style("font-weight", "bold")
        .text(nutrient);
    });

    // Color scale for different food items
      const colorScale = d3.scaleOrdinal(d3.schemeCategory10);

      // ======================================================00

    console.log(colorScale);
    
    // Draw parallel paths for each food item
    itemsToDraw.forEach((item, index) => {
      const nutrientValues = displayedNutrients.map((nutrient) => ({
        nutrient,
        value: item.food[nutrient] || 0,
      }));

      const line = d3.line()
        .x((d) => xScale(d.nutrient))
        .y((d) => yScales[d.nutrient](d.value))
        .curve(d3.curveMonotoneX);

      svg.append("path")
        .datum(nutrientValues)
        .attr("fill", "none")
        .attr("stroke", item.color)
        .attr("stroke-width", hoveredItem?.id === item.food.id ? 6 : 2)  // Thicker if hovered
        .attr("opacity", hoveredItem?.id === item.food.id ? 1 : 0.6)  // Adjust opacity
        //.attr("stroke-width", 2)
        //.attr("opacity", 0.7)
        .attr("d", line)
        //.on("mouseover", () => setHoveredItem(item.food))  //  Detect hover
        //.on("mouseout", () => setHoveredItem(null));  //  Reset when not hovered
    });

      //const colorScale = d3.scaleOrdinal(d3.schemeCategory10);

      // ======================================================00

      svg.selectAll(".parallel-line")
          .data(itemsToDraw)
          .enter()
          .append("path")
          .attr("class", "parallel-line")
          .attr("fill", "none")
          .attr("stroke", (d) => d.color)
          .attr("stroke-width", (d) => (hoveredItem?.food?.id === d.food.id ? 6 : 2))  //  Thicker line when hovered!
          .attr("opacity", (d) => (hoveredItem?.food?.id === d.food.id ? 1 : 0.6))  //  More visible
          .attr("d", (d) => {
              const nutrientValues = displayedNutrients.map((nutrient) => ({
                  nutrient,
                  value: d.food[nutrient] || 0,
              }));
              return d3.line()
                  .x((d) => xScale(d.nutrient))
                  .y((d) => yScales[d.nutrient](d.value))
                  .curve(d3.curveMonotoneX)(nutrientValues);
          });

  }, [foodItems, displayedNutrients, selectedItems, hoveredItem]);  //  Re-run effect when hover changes
  //}, [foodItems, displayedNutrients, selectedItems]);

  return <svg ref={svgRef}></svg>;
}

export default ParallelSets;
