import { useEffect, useRef } from "react";
import * as d3 from "d3";

function RadialBar({ addedFoodItems, displayedNutrients, goals, hover, selectedItems }) {
  const svgRef = useRef();
  
  useEffect(() => {
    const width = 850;
    const height = 800;
    const legendBarWidth = 300;
    const innerRadius = 30;
    const outerRadius = Math.min(width, height) / 2;
    const labelsAngle = Math.PI / 20;

    const nutrientIntake = displayedNutrients.map((nutrient) => {
      const nutrientData = { nutrient, totalIntake: 0 };
      addedFoodItems.forEach((foodItem) => {
        const rdi = goals[nutrient] || 1;
        nutrientData["totalIntake"] +=
          (foodItem.food[nutrient] * foodItem.weight) / (rdi * 100) || 0;
      });
      return nutrientData;
    });

    console.log("goal", goals);
    

    // ✅ Clear previous SVG
    d3.select(svgRef.current).selectAll("*").remove();

    // ✅ Create Tooltip
    const tooltip = d3
      .select("body")
      .append("div")
      .attr("class", "tooltip")
      .style("position", "absolute")
      .style("background", "white")
      .style("border", "1px solid black")
      .style("border-radius", "5px")
      .style("padding", "5px")
      .style("font-size", "12px")
      .style("display", "none");

    // ✅ Create SVG
    const svg = d3
      .select(svgRef.current)
      .attr("viewBox", `0 0 ${width} ${height}`)
      .attr("width", width + legendBarWidth)
      .attr("height", height)
      .attr("style", "max-width: 100%; height: auto;")
      .append("g")
      .attr("transform", `translate(${width / 2}, ${height / 2})`);

    // ✅ Scale for bar angles (nutrients instead of food)
    const xScale = d3
      .scaleBand()
      .domain(displayedNutrients)
      .range([labelsAngle / 2, 2 * Math.PI - labelsAngle / 2])
      .align(0);

    // ✅ Scale for radial height (total % of RDI)
    const yScale = d3
      .scaleLinear()
      .domain([0, 1.4]) // ✅ Extended to 150% to see overages
      .range([innerRadius, outerRadius]);

    var barColor = d3
      .scaleLinear()
      .domain([0,0.2,0.4, 0.6,0.8, 1, 1.2, 1.4])
      .range([
        "rgb(220, 237, 239)",
        "rgb(195, 234, 233)",
        "rgb(189, 231, 234)",
        "rgb(144, 199, 184)",
        "rgb(138, 184, 173)",
        "rgb(118, 171, 160)",
        "rgb(238, 190, 58)",
        "rgba(255, 0, 60, 0.5)",
      ]) 

     // Colorset for legend bar
  const colorSet = [
    ["0% RDI", "rgb(220, 237, 239)"],
    ["20% RDI", "rgb(195, 234, 233)"],
    ["40% RDI", "rgb(189, 231, 234)"],
    ["60% RDI", "rgb(144, 199, 184)"],
    ["80% RDI", "rgb(138, 184, 173)"],
    ["100% RDI", "rgb(118, 171, 160)"],
    ["120% RDI", "rgb(238, 190, 58)"],
    ["140% RDI", "rgba(255, 0, 60, 0.5)"],
    ];

  const legend = svg.append("g")
    .attr("class", "legend")
    .attr("transform", `translate(${width / 2 - 100}, 0)`); // to make sure the legend baris  within the SVG bounds

    legend.selectAll("rect")
        .data(colorSet)
        .enter()
        .append("rect")
        .attr("x", 0)
        .attr("y", (d, i) => i * 35) // Increase spacing for each color
        .attr("width", 30)
        .attr("height", 30)
        .style("fill", (d) => d[1]); // Access color with d[1]

    legend.selectAll("text")
      .data(colorSet)
      .enter()
      .append("text")
      .attr("x", 40) // text added to the right of the color box
      .attr("y", (d, i) => i * 35 + 20) // Center the text vertically
      .text((d) => d[0])
      .style("font-size", "12px")
      .style("fill", "#333");

    let ticks = [0, 0.2, 0.4, 0.6, 0.8, 1];

    // ✅ Add complete circle in the background
   
    nutrientIntake.forEach((nutrient) => {
      svg
        .append("g")
        .selectAll("g")
        .data([nutrient])
        .enter()
        .append("path")
        .attr("fill", (d) => barColor(d.totalIntake))
        .attr("fill-opacity", () =>
          hover ? 0.5 : selectedItems.length > 0 ? 0.4 : 0.9
        )
        .attr(
          "d",
          d3
            .arc()
            .innerRadius(innerRadius)
            .outerRadius((d) => yScale(d.totalIntake))
            .startAngle((d) => xScale(d.nutrient))
            .endAngle((d) => xScale(d.nutrient) + xScale.bandwidth())
            .padAngle(0.03)
            .padRadius(innerRadius)
        );
    });

    svg
      .selectAll("circle")
      .data(ticks)
      .join((enter) =>
        enter
          .append("circle")
          .attr("cx", 0)
          .attr("cy", 0)
          .attr("r", (d) => yScale(d))
          .attr("fill", "none")
          .attr("stroke", "#aaa")
          .attr("stroke-width", 0.5)
      );

    svg
      .append("g")
      .selectAll("g")
      .data(nutrientIntake)
      .enter()
      .append("path")
      .attr("fill", "transparent")
      .attr("opacity", 0.15)
      .attr(
        "d",
        d3
          .arc()
          .innerRadius(innerRadius - 2)
          .outerRadius(yScale(1.1))
          .startAngle(-labelsAngle / 2)
          .endAngle(labelsAngle / 2)
          .padAngle(0.01)
          .padRadius(innerRadius)
      );

    svg
      .selectAll(".ticklabel")
      .data(ticks)
      .join((enter) =>
        enter
          .append("text")
          .attr("class", "ticklabel")
          .style("font-size", "10px")
          .attr("x", (d) => {
            if (d === 0) {
              return -7;
            }
            if (d === 1) {
              return -12;
            }
            return -9;
          })
          .attr("y", (d) => -yScale(d) + 4)
          .text((d) => (d * 100).toString() + "%")
      );

    let lineAngles = [];
    for (var i = 0; i < displayedNutrients.length + 1; i++) {
      lineAngles.push(
        labelsAngle / 2 +
          (i * (2 * Math.PI - labelsAngle)) / displayedNutrients.length
      );
    }

    svg
      .selectAll("line")
      .data(lineAngles)
      .join((enter) =>
        enter
          .append("line")
          .attr("x1", (d) => Math.sin(d) * yScale(-0.015))
          .attr("y1", (d) => -Math.cos(d) * yScale(-0.015))
          .attr("x2", (d) => Math.sin(d) * yScale(1))
          .attr("y2", (d) => -Math.cos(d) * yScale(1))
          .attr("stroke", "#ddd")
      );

    const labels = svg
      .append("g")
      .selectAll("g")
      .data(nutrientIntake)
      .enter()
      .append("g")
      .attr("transform", (d) => {
        const angle = xScale(d.nutrient) + xScale.bandwidth() / 2 - Math.PI / 2;
        const x = Math.cos(angle) * (outerRadius - innerRadius);
        const y = Math.sin(angle) * (outerRadius - innerRadius);
        return `translate(${x}, ${y})`;
      });

    // ✅ Add Nutrient Name
    labels
      .append("text")
      .attr("text-anchor", "middle")
      .text((d) => d.nutrient)
      .style("font-size", "15px")
      .style("fill", "#3C4044")
      .style("font-weight", "bold");

    // ✅ Add RDI % Directly Below Nutrient Name
    if (!hover) {
      labels
        .append("text")
        .attr("text-anchor", "middle")
        .attr("dy", "17px") // Offset below the nutrient name
        .text((d) => Math.round(d.totalIntake * 10000) / 100 + "% RDI")
        .style("font-size", "15px")
        .style("fill", "#333");
    }

    // ✅ Remove tooltip on component unmount
    return () => {
      tooltip.remove();
    };
  }, [addedFoodItems, displayedNutrients, goals, hover]);

  return (
    <div style={styles.radialBar}>
      <svg ref={svgRef}></svg>
    </div>
  );
}

export default RadialBar;

const styles = {
  radialBar: { textAlign: "center", alignItems: "flex-start", display: "flex" },
};