function FoodsToCompareListItem({
  compareList,
  setCompareList,
  foodItem,
  setHighlightedFood,
}) {
  let tempList = [];
  let index = null;

  const handleFooditemOnMouseOver = () => {
    setHighlightedFood(foodItem)
  };

  const handleFooditemOnMouseOut = () => {
    setHighlightedFood(null)
  };

  const handleOnClick = () => {
    tempList = [...compareList];
    index = compareList.indexOf(foodItem);
    tempList.splice(index, 1);
    setCompareList(tempList);
  }

  return (
    <div
    style={styles.foodName}
      onClick={handleOnClick}
      key={foodItem}
      onMouseOver={handleFooditemOnMouseOver}
      onMouseOut={handleFooditemOnMouseOut}
    >
      {foodItem}
    </div>
  );
}

export default FoodsToCompareListItem;

const styles = {
  foodName: {
    fontSize: "16px",
    fontWeight: "bold",
    color: " #577A82",
    textAlign: "center", // 🔹 Forces text alignment to the left
    alignSelf: "center", // 🔹 Overrides `alignItems: "center"` from parent
  }
}