import { useState } from "react";
import SearchCategories from "./SearchCategories";
import SearchResultList from "./SearchResultList";

const SearchResultsContainer = ({ results, onAddFood }) => {
  const [selectedCategories, setSelectedCategories] = useState([]);

  const filteredResults = selectedCategories.length
    ? results.filter((item) => selectedCategories.includes(item.group))
    : results;

  return (
    <div style={styles.container}>
      <SearchCategories
        results={results}
        onCategorySelect={setSelectedCategories}
      />
      <SearchResultList results={filteredResults} onAddFood={onAddFood} />
    </div>
  );
};

const styles = {
  container: {
    display: "flex",
    flexDirection: "row",
    position: "absolute",
    top: "100%", // Position it below the input field
    left: "0",
    width: "600px",
    zIndex: 10, // Ensure it appears above other elements
    backgroundColor: "white", // Optional: to make it stand out
    borderTop: "2px solid #3C4244", 
    backgroundColor: "rgba(252, 244, 232, 0.9)",
  },
};

export default SearchResultsContainer;
