import { useState } from "react";
import AddedFoodListItem from "./AddedFoodListItem";
import StackedBarChart from "../ChartComponents/StackedBarChart";
import { max } from "d3";

function AddedFoodTable({
  foodItems,
  onRemoveItem,
  onWeightChange,
  setHoveredItem,
  compareActivated,
  selectedItems,
  onSelectedItems,
  displayedNutrients
}) {
  const [editingWeight, setEditingWeight] = useState(null);
  const [tableHoveredItem, setTableHoveredItem] = useState(null);

  return (
  <div style={{ display: "flex", flexDirection: "row", gap: "20px" }}>
    <div style={styles.listContainer}>
      {foodItems.length > 0 ? (
        foodItems.map((listItem, index) => (
          <div
          key={index}
          style={{ display: "flex", alignItems: "center", gap: "20px" }}
          onMouseEnter={() => setTableHoveredItem(listItem)}
          onMouseLeave={() => setTableHoveredItem(null)}
        >
      <AddedFoodListItem
        editingWeight={editingWeight}
        setEditingWeight={setEditingWeight}
        onRemoveItem={onRemoveItem}
        onWeightChange={onWeightChange}
        listItem={listItem}
        index={index}
        setHoveredItem={setHoveredItem}
        key={index}
        compareActivated={compareActivated}
        selectedItems={selectedItems}
        onSelectedItems={onSelectedItems}
      />
     {/* {tableHoveredItem===listItem && (
            <div style={styles.chartContainer}>
              <StackedBarChart chartData={tableHoveredItem}  displayedNutrients={displayedNutrients} width={150} />
            </div>
          )} */}
  </div>
        ))
      ) : (
        <div style={styles.listItem}>No food items added yet.</div>
      )}
    </div>
     
  </div>
  );
}

export default AddedFoodTable;
const styles = {
  listContainer: {
    width: "100%",
    maxWidth: "550px",
    maxHeight: "550px",
    overflowY: "auto", 
  },
  listItem:{
    display: "flex",
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "flex-start",
    padding: "10px",
    borderBottom: "1px solid #ddd",
    cursor: "pointer",
  }
  
};
