import ParallellCoordsChart from "./ParallellCoordsChart";
import ChartFilter from "../ChartFilter";
import { useState } from "react";
import SelectedFooditemsList from "./SelectedFooditemsListComponents/SelectedFooditemsList";
import fullFoodData from "../../Data/fullFoodData.json";
import FilterGroupsFilter from "./FilterGroupsFilterComponents/FilterGroupsFilter";
import filterGroups from "../../Data/filterGroups.json";
import FoodsToCompare from "./SelectedFooditemsListComponents/FoodsToCompare";

function ExplorationView() {
  const nutrientOptions = [
    "Calcium",
    "Carbohydrates",
    "Energy",
    "Fat",
    "Fibre",
    "Protein",
    "Salt",
    "Sodium",
    "Vitamin C",
    "Vitamin D",
    "Zinc",
  ];

  const colors = {
    "Fat, oil": "#de9664",
    Meals: "#7b63d4",
    "Sandwich filling": "#5cc953",
    Dairy: "#c34fb8",
    Drink: "#53a42d",
    Miscellaneous: "#d5467f",
    Bread: "#58c36d",
    Flour: "#cf3c44",
    Potatoes: "#55c4a6",
    "Vegetables, leguminous, mushrooms": "#db622e",
    "Fruit, berry": "#3abbcc",
    Flavouring: "#d69f33",
    "Quorn, soy protein": "#686ab4",
    "Cereal, breakfast cereal, muesly": "#acbc38",
    "Pasta, rice, grains": "#cd8acd",
    "Nutrient supply": "#5b8e31",
    Sausage: "#9a4b7b",
    Icecream: "#72c181",
    Meat: "#cc6e75",
    Poultry: "#47975a",
    "Fish, shellfish": "#6599d8",
    "Egg, roe, caviare": "#8d8f2d",
    "Liver, kidney, tounge etc.": "#a4552e",
    "Nuts, seeds": "#308568",
    Snacks: "#8f6f2f",
    "Buns, soft cakes, pastry": "#35743b",
    "Jam, marmelade, chutney": "#b1b36b",
    Candy: "#616d2c",
  };
  const [highlightedFood, setHighlightedFood] = useState(null);
  const [selectedFooditems, setSelectedFooditems] = useState(fullFoodData);
  const [displayedNutrients, setDisplayedNutrients] = useState(nutrientOptions);
  const [compareList, setCompareList] = useState([]);
  const [compareMode, setCompareMode] = useState(false);
  const [displayedFilterGroups, setDisplayedFilterGroups] =
    useState(filterGroups);
  const [hoveredFilterGroup, setHoveredFilterGroup] = useState(null);

  const handleDisplayedChange = (selectedOptions) => {
    setDisplayedNutrients(selectedOptions);
  };

  const handleDisplayedFilterGroupsChange = (visibleFilterGroups) => {
    setDisplayedFilterGroups(visibleFilterGroups);
  };

  return (
      <div style={styles.container}>
        <div style={styles.topSection}>
          <ChartFilter
            onSelectionChange={handleDisplayedChange}
            nutrientOptions={nutrientOptions}
          />
          <FilterGroupsFilter
            displayedFilterGroups={displayedFilterGroups}
            onDisplayedFilterGroupsChange={handleDisplayedFilterGroupsChange}
            colors={colors}
            setHoveredFilterGroup={setHoveredFilterGroup}
            setSelectedFooditems={setSelectedFooditems}
          />
        </div>
        <div style={styles.chartWrap}>
        <ParallellCoordsChart
          displayedNutrients={displayedNutrients}
          setSelectedFooditems={setSelectedFooditems}
          displayedFilterGroups={displayedFilterGroups}
          colors={colors}
          hoveredFilterGroup={hoveredFilterGroup}
          compareList={compareList}
          compareMode={compareMode}
          highlightedFood={highlightedFood}
        />
        </div>

        <div style={styles.bottomSection}>
          <div  style={styles.left}>
        <SelectedFooditemsList
          selectedFooditems={selectedFooditems}
          displayedNutrients={displayedNutrients}
          setHighlightedFood={setHighlightedFood}
          setCompareList={setCompareList}
          compareList={compareList}
         
        /></div>
        <div  style={styles.right}>
        <FoodsToCompare
          compareList={compareList}
          setCompareList={setCompareList}
          compareMode={compareMode}
          setCompareMode={setCompareMode}
          setHighlightedFood={setHighlightedFood}
          
        /></div>
      </div>


      </div>

      
  );
}

const styles = {
  container: {
    width: "100%",
    height: "100%",
    backgroundColor: "transparent",
    // padding: "30px",
    // margin: "auto",
    display: "flex",
    flexDirection: "column",
    // gap: "20px",
    overflowY: "hidden",
  },
  topSection: {
    display: "flex",
    flexDirection: "row",
    width:"100%",
    height:"20%"
  },
  chartWrap:{
    width:"100%",
    // justifyContent: "center",
    height:"45%"
  },
  bottomSection:{
    display: "flex",
    flexDirection: "row",
    width:"100%",
    

  },
  left:{
    width:"70%",
    height:"100%",
    
  },
  right:{
    width:"30%",
    // backgroundColor: 'rgba(14, 24, 209, 0.7)',
  }
};

export default ExplorationView;
