import RadarChart from "./RadarChart";
import RadialBar from "./RadialBar";
import RadarChartCompare from "./RadarChartCompare";
import StackedBarChart from "./StackedBarChart";
import ParallelSets from "./ParallelSets";

function Charts({ addedFoodItems, displayedNutrients, goals, hoveredItem, selectedItems,compareActivated, comparingItem}) {



console.log(selectedItems);



  //return addedFoodItems ? (
    return (
    <>
    <div style={{ position: "relative" }}>
      
      {hoveredItem && (
        <div style={{ position: "absolute" }}>
          <RadarChart
            displayedNutrients={displayedNutrients}
            goals={goals}
            hoveredItem={hoveredItem}
            selectedItems={selectedItems}
          />
        </div>
      )}
      {selectedItems && (
        <div style={{ position: "absolute" }}>
          <RadarChartCompare
            displayedNutrients={displayedNutrients}
            goals={goals}
            selectedItems={selectedItems}
            compareActivated={compareActivated}
            comparingItem={comparingItem}
          />
        </div>
      )}
      <RadialBar
        addedFoodItems={addedFoodItems}
        goals={goals}
        displayedNutrients={displayedNutrients}
        hover={hoveredItem}
        selectedItems={selectedItems}
        compareActivated={compareActivated}
        />
    </div>

    {/* always render ParallelSets, even if no items are added */}
    <ParallelSets
        foodItems={addedFoodItems || []}  // Ensure it gets an empty array instead of null/undefined
        displayedNutrients={displayedNutrients}
        selectedItems={selectedItems}
        comparingItem={comparingItem}
        hoveredItem={hoveredItem}  // Pass hoveredItem
    />
</>
);


    //</div>
    //<ParallelSets foodItems={addedFoodItems} displayedNutrients={displayedNutrients} selectedItems={selectedItems} comparingItem={comparingItem} />
    //</>
  //) : (
    //""
  //);
}

export default Charts;
