import { useState, useMemo } from "react";
import DataTable from 'datatables.net-react';
import DT from 'datatables.net-dt';
 
DataTable.use(DT);

function SelectedFooditemsList ({selectedFooditems, displayedNutrients, setHighlightedFood, compareList, setCompareList}) {


    const columns = useMemo(() => [
        { data: "name", title: "Name"}, 
        ...displayedNutrients.map(nutrient => ({ data: nutrient, title: nutrient}))
    ], [displayedNutrients]);
    
    const addToCompareList = (foodItem) => {
        setCompareList((prevList) =>
            prevList.includes(foodItem)
                ? prevList
                : [...prevList, foodItem]
        ); 
    };

    return (
        <div className="tableWrapper">
        <div className="tableContainer" >
            <DataTable 
            key={displayedNutrients.join(",")}
            data={selectedFooditems} 
            columns={columns} 
            options={{
                autoWidth: false,

                // scrollY: "400px", // Set table height with scroll
                // scrollCollapse: true,
                // paging: false,
                columnDefs:[
                {targets: 0, width: "200px", },
                {targets: "_all", width:"200px"}
                ],
                createdRow: function(row, dataIndex){
                    row.addEventListener("mouseenter", () =>{
                        setHighlightedFood(dataIndex["name"]);
                        row.style.backgroundColor = "#d3d3d3";
                    })
                    row.addEventListener("mouseleave", () =>{
                        setHighlightedFood(null);
                        row.style.backgroundColor = "";
                    })
                    row.addEventListener("click", () =>{
                        addToCompareList(dataIndex["name"])
                    })
                }
            }} />
              
        </div>
        </div>
    )
}


export default SelectedFooditemsList

const styles = {
   
    table: {
        width: "100%", 
        height:"100%",
        maxWidth: "100%" 
    }
}