// src/Filter.js
import { useState, useEffect } from "react";

function ChartFilter({ onSelectionChange, nutrientOptions }) {

  const macros = ["Energy", "Fat", "Protein", "Carbohydrates","Fibre"];
  const [selectedOptions, setSelectedOptions] = useState(macros);

  const handleOptionClick = (option) => {
    setSelectedOptions(
      (prevSelected) =>
        prevSelected.includes(option)
          ? prevSelected.filter((item) => item !== option) // Remove if already selected
          : [...prevSelected, option] // Add if not selected
    );
  };

  useEffect(() => {
    onSelectionChange(selectedOptions);
  }, [selectedOptions, onSelectionChange]);

  return (
    <div>
    <div style={styles.titleWrap}>
                  <div style={styles.nutrientsTitle}>Displayed Nutrients</div>
                </div>
    <div style={styles.container}>
      {nutrientOptions.map((option) => (
        <div key={option} style={styles.filterItem} onClick={() => handleOptionClick(option)}>
          <div
            style={{
              ...styles.circle,
              backgroundColor: selectedOptions.includes(option) ?  "rgb(118, 171, 160)" : "#E1D1BF",
            }}
          />
          <span style={styles.text}>{option}</span>
        </div>
      ))}
    </div>
    </div>
  );
}

const styles = {
  titleWrap: {
    width: "100%",
    textAlign: "left",
    // paddingBottom: "10px",
  },
  nutrientsTitle: {
    fontSize: "16px",
    fontWeight: "bold",
    color: "#577A82",
    textAlign: "left",
    // fontFamily: "Times",
  },
  container: {
    display: "flex",
    flexWrap: "wrap",
    justifyContent: "flex-start",
    padding: "10px",
  },
  filterItem: {
    display: "flex",
    alignItems: "center",
    gap: "8px",
    cursor: "pointer",
    padding: "5px 6px",
  },
  circle: {
    width: "16px",
    height: "16px",
    borderRadius: "50%",
  },
  text: {
    fontSize: "14px",
    color: "#333",
  },
};
export default ChartFilter;
