function AddedFoodListItem({
  onRemoveItem,
  onWeightChange,
  editingWeight,
  setEditingWeight,
  listItem,
  index,
  setHoveredItem,
  compareActivated,
  selectedItems,
  onSelectedItems,
}) {
  const handleHover = (e) => {
    e.stopPropagation()
    if (e.type === "mouseover") {
      setHoveredItem(listItem);
    } else if (e.type === "mouseout") {
      setHoveredItem(null);
    }
  };

  const selectedItem = selectedItems.find(
    (item) => item.id === listItem.food.id
  );
  const isSelected =
    compareActivated &&
    Array.isArray(selectedItems) &&
    selectedItems.some((item) => item.id === listItem.food.id);

  const handleSelected = (event) => {
    event.stopPropagation()
    if (!compareActivated) return;

    const colorPalette = [
      "#e377c2", // Pink
      "#ff7f0e", // Orange
      "#2ca02c", // Green
      "#d62728", // Red
      "#9467bd", // Purple
      "#8c564b", // Brown
      "#1f77b4", // Blue
      "#7f7f7f", // Gray
      "#bcbd22", // Yellow-Green
      "#17becf"  // Cyan
    ];

    // ✅ Check if the item is already selected
    const existingItem = selectedItems.find(
      (item) => item.id === listItem.food.id
    );

    let newSelectedItems;

    if (existingItem) {
      // ✅ Remove the item while keeping others unchanged
      newSelectedItems = selectedItems.filter(
        (item) => item.id !== listItem.food.id
      );
    } else {
      // ✅ Check if the item already has a color assigned
      const usedColors = selectedItems.map((item) => item.color);
      const availableColor =
        colorPalette.find((color) => !usedColors.includes(color)) || "#000000"; // Fallback color

      const newItem = {
        id: listItem.food.id,
        weight: listItem.weight,
        color: availableColor, // ✅ Assigns a new color only when needed
      };

      newSelectedItems = [...selectedItems, newItem];
    }

    // ✅ Send updated selected items with their colors
    onSelectedItems(newSelectedItems);
  };

  return (
    <div
      key={index}
      style={{
        ...styles.listItem,
        ...(isSelected ? styles.selectedItem : {}),
        borderColor: isSelected ? selectedItem?.color || "#C3E6CB" : "#577A82",
      }}
      onMouseOver={handleHover}
      onMouseOut={handleHover}
      onClick={compareActivated ? handleSelected : undefined}
    >
      <button
        style={styles.removeButton}
        onClick={(e) => {
          e.stopPropagation();
          onRemoveItem(listItem.food.id)}}
      >
        X
      </button>

      <div style={styles.foodNameWrapper}>
        <div style={styles.foodName}>{listItem.food.name}</div>
        <div style={styles.infoGp}>
          <div
            style={styles.weightContainer}
            onClick={() => setEditingWeight(listItem.food.id)}
          >
            {editingWeight === listItem.food.id ? (
              <input
                type="number"
                value={listItem.weight}
                onChange={(e) =>
                  onWeightChange(listItem.food.id, e.target.value)
                }
                onBlur={() => setEditingWeight(null)} // Exit edit mode when focus is lost
                autoFocus
                style={styles.weightInput}
              />
            ) : (
              <span style={styles.weightText}>{listItem.weight}g</span>
            )}
          </div>
          <div style={styles.foodGroup}>{listItem.food["Filter group"]}</div>
        </div>
      </div>
    </div>
  );
}

const styles = {
  listContainer: {
    width: "500px",
    backgroundColor: "rgba(225, 150, 11, 0.7)",
    // gap: "20px",
  },
  listItem: {
    display: "flex",
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "flex-start",
    cursor: "pointer",
    padding: "20px 0",
    width: "550px",
    borderBottom: "2px solid #577A82", // Divider line
    backgroundColor: "transparent",
    borderStyle: "solid",
    borderWidth: "0px 0px 2px 0px",
    // borderColor: "#577A82",
  },
  selectedItem: {
    backgroundColor: "rgba(147, 202, 214, 0.33)", // Change background when selected
    borderBottom: "5px solid #577A82", // Divider line
    // backgroundColor: 'transparent',
    borderStyle: "solid",
  },

  foodGroup: {
    fontSize: "14px",
    fontWeight: "bold",
    flexDirection: "row",
    color: "rgba(152, 103, 38, 0.7)",
    // minWidth: "100px",
    textAlign: "right",
  },

  foodNameWrapper: {
    width: "100%", // 🔹 Ensures it spans the full width
    display: "flex",
    flexDirection: "column",
    gap: "5px",
  },

  foodName: {
    fontSize: "16px",
    fontWeight: "bold",
    color: "rgba(60, 64, 68, 0.9)",
    textAlign: "left", // 🔹 Forces text alignment to the left
    alignSelf: "flex-start", // 🔹 Overrides `alignItems: "center"` from parent
  },
  infoGp: {
    display: "flex",
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "flex-start",
    width: "100%",
    gap: "20px",
  },
  weightContainer: {
    cursor: "pointer",
    textAlign: "left",
    // backgroundColor: "#fff",
    // borderRadius: "10px",
    // minWidth: "100px",
    // padding: "5px",
    // borderBottom: "2px solid rgba(93, 161, 117, 0.7)", // Divider line
  },

  weightText: {
    fontSize: "16px",
    fontWeight: "500",
    color: "rgba(60, 64, 68, 0.9)",
  },

  weightInput: {
    // width: "50px",
    // padding: "5px",
    border: "1px solid #ccc",
    borderRadius: "5px",
    textAlign: "center",
    fontSize: "18px",
  },

  removeButton: {
    width: "30px",
    height: "30px",
    border: "none",
    borderRadius: "50%",
    backgroundColor: "transparent",
    color: "rgba(187, 73, 73, 0.7)",
    fontSize: "16px",
    fontWeight: "bold",
    cursor: "pointer",
    display: "flex",
    alignItems: "right",
    justifyContent: "center",
    transition: "background 0.3s ease",
  },

  removeButtonHover: {
    backgroundColor: "#e04a4a",
  },
};

export default AddedFoodListItem;
