import "./App.css";
import { useState } from "react";
import Navbar from "./Components/Navbar";
import MainContent from "./Components/MainContent";
import ExplorationView from "./Components/ExplorationComponents/ExplorationView";

function App() {
  const [isExplorationOpen, setExplorationOpen] = useState(false);

  const toggleExploration = () => {
    setExplorationOpen(!isExplorationOpen);
  };

  return (
    <div className="App" style={styles.app}>
     
      <MainContent style={styles.mainContainer} />
      {isExplorationOpen && (
        <div style={styles.overlay}>
          <div style={styles.explorationContainer}>
            <button style={styles.closeButton} onClick={toggleExploration}>✖</button>
            <ExplorationView />
          </div>
        </div>
      )}
      <button style={styles.floatingButton} onClick={toggleExploration}>
        {isExplorationOpen ? "Close" : "Explore"}
      </button>
    </div>
  );
}

export default App;

