import * as d3 from "d3";
import { useRef, useEffect, useState } from "react";
import fullFoodData from "../../Data/fullFoodData.json";

function ParallellCoordsChart({
  displayedNutrients,
  setSelectedFooditems,
  displayedFilterGroups,
  colors,
  hoveredFilterGroup,
  compareList,
  compareMode,
  highlightedFood,
}) {
  const svgRef = useRef();
  const [keys, setKeys] = useState(displayedNutrients);
  const [brushExtents, setBrushExtents] = useState({});
  const [selectionsExtents, setSelectionsExtents] = useState(new Map());

  useEffect(() => {
    d3.select(svgRef.current).selectAll("*").remove();
    displayedNutrients.forEach((nutrient) => {
      if (!keys.includes(nutrient)) {
        setKeys([...keys, nutrient]);
      }
    });
    keys.forEach((key) => {
      if (!displayedNutrients.includes(key)) {
        setKeys(keys.filter((key) => displayedNutrients.includes(key)));
      }
    });

    const data = fullFoodData;
    const height = 300;
    const width = 1200;
    const marginTop = 10;
    const marginRight = 100;
    const marginBottom = 10;
    const marginLeft = 100;

    // Create an vertical (*x*) scale for each key.
    // const x = new Map(
    //   Array.from(keys, (key) => [
    //     key,
    //     d3
    //       .scalePow()
    //       .exponent(1/5)
    //       .domain(d3.extent(data, (d) => d[key]))
    //       .range([height - marginTop, marginBottom]),
    //   ])
    // );

    const x = new Map(
      Array.from(keys, (key) => [
        key,
        d3.scaleLinear(
          d3.extent(data, (d) => d[key]),
          [height - marginBottom, marginTop]
        ),
      ])
    );

    // Create the horizontal (*y*) scale.
    var y = d3.scalePoint(keys, [marginLeft, width - marginRight]);

    // Create the color scale.
    // const color = d3.scaleOrdinal(d3.schemeAccent);

    // const color = d3.scaleSequential(x.get(keyz).domain(), (t) =>
    //   d3.interpolateBrBG(1 - t)
    // );

    // Create the SVG container.
    const svg = d3
      .select(svgRef.current)
      .attr("viewBox", [0, 0, width, height])
      .attr("width", width)
      .attr("height", height)
      .attr("style", "max-width: 100%; height: auto;");

    // Append the lines.
    const line = d3
      .line()
      .defined(([, value]) => value != null)
      .y(([key, value]) => x.get(key)(value))
      .x(([key]) => y(key));

    const path = svg
      .append("g")
      .attr("fill", "none")
      .attr("stroke-width", 2)
      .selectAll("path")
      .data(
        compareMode
          ? data.filter((foodItem) => compareList.includes(foodItem["name"]))
          : hoveredFilterGroup
          ? data
          : data.filter((foodItem) =>
              displayedFilterGroups.includes(foodItem["Filter group"])
            )
      )
      .join("path")
      .attr("stroke-opacity", 0.4)
      .attr("stroke", (d) =>
        compareMode || highlightedFood
          ? colors[d["Filter group"]]
          : displayedFilterGroups.includes(d["Filter group"])
          ? colors[d["Filter group"]]
          : "#ddd"
      )
      .attr("d", (d) => line(d3.cross(keys, [d], (key, d) => [key, d[key]])))
      .call((path) => path.append("title").text((d) => d.name));

    if (hoveredFilterGroup && !compareMode) {
      d3.selectAll("path").each((d, i, nodes) => {
        if (d["Filter group"] === hoveredFilterGroup) {
          d3.select(nodes[i]).raise();
          if(!displayedFilterGroups.includes(d["Filter group"])) {
            nodes[i].setAttribute("stroke", "#aaa");
          }
        } else {
          nodes[i].setAttribute("stroke", "#ddd");
        }
      });
    }

    if (highlightedFood) {
      d3.selectAll("path").each((d, i, nodes) => {
        if (d["name"] === highlightedFood) {
          d3.select(nodes[i]).raise();
          nodes[i].setAttribute("stroke", colors[d["Filter group"]]);
        } else {
          nodes[i].setAttribute("stroke", "#ddd");
        }
      });
    }

    // Append the axis for each key.
    const axes = svg
      .append("g")
      .selectAll("g")
      .data(keys)
      .join("g")
      .attr("transform", (d) => `translate(${y(d)},0)`)
      .each(function (d) {
        d3.select(this).call(d3.axisRight(x.get(d)));
      });

    // Create axis headers
    const headers = svg
      .append("g")
      .selectAll("g")
      .data(keys)
      .join("text")
      .attr("y", marginTop - 5)
      .attr("x", (d) => y(d))
      .attr("text-anchor", "start")
      .attr("fill", "black")
      .attr("font-size", 10)
      .attr("cursor", "grab")
      .text((d) => d);

    // Create the brush behavior.
    const deselectedColor = "#ddd";
    const brushHeight = 50;
    const brush = d3
      .brushY()
      .extent([
        [-(brushHeight / 2), marginTop],
        [brushHeight / 2, height - marginBottom],
      ])
      .on("start brush end", brushed);

    if (!(hoveredFilterGroup || compareMode || highlightedFood)) {
      axes.call(brush);
    }

    const selections = selectionsExtents;

    function brushed({ selection }, key) {
      if (selection === null) selections.delete(key);
      else selections.set(key, selection.map(x.get(key).invert));
      const selected = [];
      path.each(function (d) {
        const active = Array.from(selections).every(
          ([key, [maxValue, minValue]]) => {
            let minCoordinate = x.get(key)(maxValue);
            let maxCoordinate = x.get(key)(minValue);
            let dCoordinate = x.get(key)(d[key]);
            return dCoordinate >= minCoordinate && dCoordinate <= maxCoordinate;
          }
        );
        d3.select(this).style(
          "stroke",
          active ? colors[d["Filter group"]] : deselectedColor
        );
        if (active) {
          d3.select(this).raise();
          selected.push(d);
        }
      });
      setSelectedFooditems(selected);
      svg.property("value", selected).dispatch("input");
      d3.selectAll(axes).each((d, i, k) => {
        const tempBrushExtents = brushExtents;
        tempBrushExtents[d] = d3.brushSelection(k[i]);
        setBrushExtents(tempBrushExtents);
      });
      setSelectionsExtents(selections);
    }

    if (!(hoveredFilterGroup || compareMode || highlightedFood)) {
      d3.selectAll(axes).each((d, i, k) => {
        var selection = selectionsExtents.get(d);
        if (selection !== undefined) {
          if (selection[0] < selection[1]) {
            selection = selection.reverse();
          }
          selection[0] = x.get(d)(selection[0]);
          selection[1] = x.get(d)(selection[1]);
          d3.select(k[i]).call(brush.move, selection);
        }
      });
    }

    // Axis drag behaviour
    var dragHandler = d3
      .drag()
      .on("start", started)
      .on("drag", dragged)
      .on("end", ended);

    var deltaX;

    var tempKeys = keys;

    function started(event) {
      const current = d3.select(this);
      deltaX = current.attr("x") - event.x;
      d3.selectAll(axes)
        .filter((d) => d !== current.data()[0])
        .each((_, index, foundAxes) => {
          d3.select(foundAxes[index]).attr("opacity", 0.5);
        });
      d3.selectAll(headers)
        .filter((d) => d !== current.data()[0])
        .each((_, index, foundHeaders) => {
          d3.select(foundHeaders[index]).attr("opacity", 0.5);
        });
      d3.selectAll(path).each((d, i, nodes) => {
        nodes[i].setAttribute("stroke", "#ddd");
      });
    }

    function dragged(event) {
      const interval = 40;
      const xCoordinate = event.x + deltaX;
      var updated = false;
      // Move selected axis and header
      d3.select(this).attr("x", xCoordinate);
      const movedNutrient = d3.select(this).data()[0];
      d3.selectAll(axes)
        .filter((d) => d === movedNutrient)
        .attr("transform", (d) => `translate(${xCoordinate},0)`);
      // Check if moved axis is close to other axis
      const keyIndex = tempKeys.indexOf(movedNutrient);
      if (keyIndex > 0 && xCoordinate - y(tempKeys[keyIndex - 1]) < interval) {
        tempKeys = [
          ...tempKeys.slice(0, keyIndex - 1),
          movedNutrient,
          tempKeys[keyIndex - 1],
          ...tempKeys.slice(keyIndex + 1),
        ];
        updated = true;
      } else if (
        keyIndex < tempKeys.length &&
        Math.abs(xCoordinate - y(tempKeys[keyIndex + 1])) < interval
      ) {
        tempKeys = [
          ...tempKeys.slice(0, keyIndex),
          tempKeys[keyIndex + 1],
          movedNutrient,
          ...tempKeys.slice(keyIndex + 2),
        ];
        updated = true;
      }
      if (updated) {
        y = d3.scalePoint(tempKeys, [marginLeft, width - marginRight]);
        d3.selectAll(axes)
          .filter((d) => d !== movedNutrient)
          .each((nutrient, index, foundAxes) => {
            d3.select(foundAxes[index]).attr(
              "transform",
              `translate(${y(nutrient)},0)`
            );
          });
        d3.selectAll(headers)
          .filter((d) => d !== movedNutrient)
          .each((nutrient, index, foundHeaders) => {
            d3.select(foundHeaders[index]).attr("x", y(nutrient));
          });
      }
    }

    function ended(event) {
      const movedNutrient = d3.select(this).data()[0];
      d3.select(this).attr("x", y(movedNutrient));
      d3.selectAll(axes)
        .filter((d) => d === movedNutrient)
        .attr("transform", (d) => `translate(${y(movedNutrient)},0)`);

      d3.selectAll(path).each((d, i, nodes) => {
        nodes[i].setAttribute("stroke", colors[d["Filter group"]]);
      });
      d3.selectAll(axes).each((_, index, foundAxes) => {
        d3.select(foundAxes[index]).attr("opacity", 1);
      });
      d3.selectAll(headers).each((_, index, foundHeaders) => {
        d3.select(foundHeaders[index]).attr("opacity", 1);
      });
      setKeys(tempKeys);
    }

    dragHandler(headers);

    axes.raise();
  }, [
    displayedNutrients,
    setSelectedFooditems,
    displayedFilterGroups,
    hoveredFilterGroup,
    keys,
    brushExtents,
    compareList,
    selectionsExtents,
    compareMode,
    highlightedFood,
  ]);

  return <svg ref={svgRef}></svg>;
}

export default ParallellCoordsChart;
