import FoodsToCompareListItem from "./FoodsToCompareListItem";

function FoodsToCompare({
  compareList,
  setCompareList,
  compareMode,
  setCompareMode,
  setHighlightedFood,
}) {
  const handleOnCompareFoodsClick = () => {
    setCompareMode(!compareMode);
  };

  return (
    <div>
      <div style={styles.foodTableTitle}>Foods to compare</div>
      <button style={styles.button}  onClick={handleOnCompareFoodsClick}>
        {compareMode ? "Disable compare mode" : "Enable compare mode"}
      </button>
      <div className="conent" style={styles.content}>
        {compareList.map((food) => (
          <FoodsToCompareListItem
            key={food}
            compareList={compareList}
            setCompareList={setCompareList}
            foodItem={food}
            setHighlightedFood={setHighlightedFood}
          />
        ))}
      </div>
      
    </div>
  );
}

export default FoodsToCompare;

