import { useEffect, useState } from "react";
import filterGroups from "../../../Data/filterGroups.json";
import FilterGroupsFilterItem from "./FilterGroupsFilterItem";
import fullFoodData from "../../../Data/fullFoodData.json"

function FilterGroupsFilter({
  displayedFilterGroups,
  onDisplayedFilterGroupsChange,
  colors,
  setHoveredFilterGroup,
  selectedFoodItems,
  setSelectedFooditems,
}) {
  const [selectedFilterGroups, setSelectedFilterGroups] =
    useState(filterGroups);

  const handleFilterGroupClick = (filterGroup) => {
    if (filterGroup == "Toggle all"){
      setSelectedFilterGroups(
        (prevSelected) =>
          prevSelected.includes(filterGroup)
            ? [] 
            : filterGroups
      );
    }
    else {
      setSelectedFilterGroups(
        (prevSelected) =>
          prevSelected.includes(filterGroup)
            ? prevSelected.filter((item) => item !== filterGroup) // Remove if already selected
            : [...prevSelected, filterGroup] // Add if not selected
      );
    }
  };

  useEffect(() =>{
    setSelectedFooditems(
      fullFoodData.filter((food) => 
        selectedFilterGroups.includes(food["Filter group"])
      )
    )
  }, [selectedFilterGroups, fullFoodData]);

  useEffect(() => {
    onDisplayedFilterGroupsChange(selectedFilterGroups);
  }, [selectedFilterGroups, onDisplayedFilterGroupsChange]);

  return (
    <div>
    <div style={styles.titleWrap}>
                  <div style={styles.nutrientsTitle}>Categories</div>
                </div>
    <div style={styles.container}>
      {filterGroups.map((filterGroup) => {
        return (
          <FilterGroupsFilterItem
            key={filterGroup}
            displayedFilterGroups={displayedFilterGroups}
            filterGroup={filterGroup}
            onClick={() => handleFilterGroupClick(filterGroup)}
            color={colors[filterGroup]}
            setHoveredFilterGroup={setHoveredFilterGroup}
            
          />
        );
      })}
    </div>
    </div>
  );
}

export default FilterGroupsFilter;
const styles = {
  titleWrap: {
    width: "100%",
    textAlign: "left",
    // paddingBottom: "10px",
  },
  nutrientsTitle: {
    fontSize: "16px",
    fontWeight: "bold",
    color: "#577A82",
    textAlign: "left",
    // fontFamily: "Times",
  },
  container: {
    display: "flex",
    flexWrap: "wrap",
    justifyContent: "flex-start",
    padding: "10px",
  },
}