import { useEffect } from "react";

function FilterGroupsFilterItem({
  displayedFilterGroups,
  filterGroup,
  onClick,
  color,
  setHoveredFilterGroup
}) {

  const handleOnMouseOver = () => {
    setHoveredFilterGroup(filterGroup)
  }
  
  const handleOnMouseOut = () => {
    setHoveredFilterGroup(null)
  }

  return (
    <div
    style={{
      ...styles.filterItem
      
    }}
      // style={{
      //   borderStyle: "solid",
      //   borderColor: "#aaaaaa",
      //   borderRadius: "12px",
      //   display: "flex",
      //   flexWrap: "no-wrap",
      //   gap: "2px",
      //   padding: "3px",
      //   opacity: displayedFilterGroups.includes(filterGroup) ? 1 : 0.1,
      // }}
      onClick={onClick}
      onMouseOver={handleOnMouseOver}
      onMouseOut={handleOnMouseOut}
    >
      <div
       style={{
        ...styles.circle,
        backgroundColor: color,
        opacity: displayedFilterGroups.includes(filterGroup) ? 1 : 0.1,
      }}
       
      ></div>
      <span style={styles.text}>{filterGroup}</span>
    </div>
  );
  // return displayedFilterGroups.includes(filterGroup) ? (
  //   <div onClick={onClick} style={{ background: "green" }}>
  //     {filterGroup}
  //   </div>
  // ) : (
  //   <div onClick={onClick} style={{ background: "red" }}>
  //     {filterGroup}
  //   </div>
  // );
}
export default FilterGroupsFilterItem;
const styles = {
  circle: {
    width: "16px",
    height: "16px",
    borderRadius: "50%",
  },
  text: {
    fontSize: "14px",
    color: "#333",
  },
  filterItem: {
    display: "flex",
    alignItems: "center",
    gap: "8px",
    cursor: "pointer",
    padding: "5px 6px",
  },
}